13|  constructor(rom: Uint8Array, hits: Record<HandlerId, number>) {
14|    this.rom = rom;
15|    this.hits = hits;
16|    const t = rom.length > 0x147 ? rom[0x147] : 0;
17|    const as = rom.length > 0x149 ? rom[0x149] : 0;
18|    this.isMbc1 = t === 0x01 || t === 0x02 || t === 0x03;
19|    let nb = rom.length >> 14;
20|    if (nb < 2) nb = 2;
21|    this.nRom = nb;
22|    let nr = 0;
23|    if (as === 0x02) nr = 1;
24|    else if (as === 0x03) nr = 4;
25|    else if (as === 0x04) nr = 16;
26|    else if (as === 0x05) nr = 8;
27|    else if (as === 0x01) nr = 1;
28|    if (!this.isMbc1) {
29|      if (nr === 0 && (t === 0x02 || t === 0x03)) nr = 1;
30|    }
31|    if (nr > 4 && this.isMbc1) nr = 4;
32|    if (nr > 16) nr = 16;
33|    this.nRam = nr;
34|    this.ram = new Uint8Array(nr * 8192);
35|    this.ram.fill(0xff);
36|  }
