39|      if (this.isMbc1 && this.mode === 1) {
40|        const b = (this.hi << 5) % this.nRom;
41|        const o = b * 0x4000 + a;
42|        return o < this.rom.length ? this.rom[o] : 0xff;
43|      }
44|      return a < this.rom.length ? this.rom[a] : 0xff;
45|    }
46|    const b = ((this.hi << 5) | this.lo) % this.nRom;
47|    const o = b * 0x4000 + (a - 0x4000);
