// Trace executed PCs + PPU/IRQ state using only the public Core API.
import { readFileSync } from 'node:fs';
const romsRoot = process.env.RATCHET_ROMS;
const rom = process.argv[2];
const { createCore } = await import('/tmp/dbg/c1/index.ts');
const romBytes = new Uint8Array(readFileSync(romsRoot + '/' + rom));
const core = createCore(romBytes);
const hist = []; // [cycles, pc, op, ly, mode, dot, stat, IF]
let n = 0;
const execCount = new Map();
for (;; n++) {
  const pc = core.cpu.pc;
  const op = core.read(pc);
  if (op === 0x40) {
    const c = core.cpu;
    console.log(`TRAP step=${n} cycles=${core.cycles} regs ${c.b}/${c.c}/${c.d}/${c.e}/${c.h}/${c.l}`);
    break;
  }
  if (core.cycles > 30*4194304) { console.log('CAP'); break; }
  execCount.set(pc, (execCount.get(pc)||0)+1);
  if (hist.length < 400000) {
    const p = core.tap.ppu();
    hist.push([core.cycles, pc, op, p.ly, p.mode, p.dot, p.stat, core.read(0xff0f)]);
  }
  core.step();
}
// print last 60 steps
console.log(`--- last steps (total ${n}) ---`);
for (const [cy,pc,op,ly,mo,dot,st,iff] of hist.slice(-60))
  console.log(`cy=${cy} pc=${pc.toString(16).padStart(4,'0')} op=${op.toString(16).padStart(2,'0')} ly=${ly} m=${mo} d=${dot} stat=${st.toString(16)} if=${iff.toString(16)}`);
// executed ranges
const pcs = [...execCount.keys()].sort((a,b)=>a-b);
let s=-1,p=-2; const ranges=[];
for (const a of pcs) { if (a===p+1) {p=a;continue;} if(s>=0)ranges.push([s,p]); s=a;p=a; }
if(s>=0)ranges.push([s,p]);
console.log('--- executed ranges ---');
for (const [a,b] of ranges) console.log(`${a.toString(16).padStart(4,'0')}-${b.toString(16).padStart(4,'0')} (${b-a+1} bytes)`);
