// Probe format: LD HL,xxxx(3M) LD A,xx(2M) LDH (FF40),A(3M) then seq of NOP(1M)/LD A,(DE)(2M)/LD (HL+),A(2M)
function parse(a){
  // find LDH (FF40)
  if(rom[a]!==0x21) throw 'no LD HL at '+a.toString(16);
  if(rom[a+3]!==0x3E) throw 'no LD A at '+a.toString(16);
  if(rom[a+5]!==0xE0||rom[a+6]!==0x40) throw 'no LDH40 at '+a.toString(16);
  let t=0; // M-cycles since end of LDH write M-cycle... LDH = fetch,imm,write(3rd M)
  let p=a+7; const samples=[];
  while(true){
    const op=rom[p];
    if(op===0x00){t+=1;p+=1;continue;}
    if(op===0x1A){ // LD A,(DE): fetch(1M)+read(1M); read data in 2nd M
      // sample read M-cycle = t+1..t+2 (2nd M). Record start offset.
      samples.push({at:p, readM:t+1}); t+=2; p+=1; continue;
    }
    if(op===0x22){t+=2;p+=1;continue;} // LD (HL+),A
    break;
