891|        if (gb->fetcher_state == GB_FETCHER_GET_TILE_DATA_LOWER_T2) {
892|            *cgb_d_glitch = true;
893|            return 0;
894|        }
895|        return 0;
896|    }
897|    return gb->data_for_sel_glitch;
