  function ioRead(a: number): number {
    switch (a) {
      case 0xff00: {
        const sel = p1 & 0x30;
        const dir = (joyMask & 0x0f);
        const btn = ((joyMask >> 4) & 0x0f);
        let v = 0x0f;
