  function poke(a: number, v: number): void {
    v &= 0xff;
    if (a < 0x8000) { cart.write(a, v); return; }
    if (a < 0xa000) { ppu.vram[a - 0x8000] = v; return; }
    if (a < 0xc000) { cart.writeRam(a, v); return; }
