      case 0xff47: case 0xff48: case 0xff49: case 0xff4a: case 0xff4b:
        ppu.writeReg(a, v, raise);
        break;
      case 0xff44: break;
      default:
        if (a >= 0xff10 && a <= 0xff3f) audio[a - 0xff00] = v;
        break;
    }
  }

