1|import type { HandlerId } from "../src/schema.ts";
2|export class Ppu {
3|  vram = new Uint8Array(0x2000);
4|  oam = new Uint8Array(0xa0);
5|  fb = new Uint8Array(160 * 144);
6|  lcdc = 0x91; stat = 0x85 & 0xf8; scy = 0; scx = 0; ly = 0; lyc = 0;
7|  bgp = 0xfc; obp0 = 0xff; obp1 = 0xff; wy = 0; wx = 0;
8|  dot = 0; mode: 0 | 1 | 2 | 3 = 2; winLine = 0; statLine = false;
9|  m3len = 172; lineSprites: number[] = [];
10|  hits: Record<HandlerId, number>;
11|  constructor(hits: Record<HandlerId, number>) { this.hits = hits; this.resetStatLine(); }
12|  get on(): boolean { return (this.lcdc & 0x80) !== 0; }
13|  resetStatLine(): void { this.statLine = this.computeStatLine(); }
14|  computeStatLine(): boolean {
15|    if (!this.on) return false;
16|    const s = this.stat;
17|    const lycEq = (this.stat & 0x04) !== 0;
18|    if ((s & 0x40) && lycEq) return true;
19|    if ((s & 0x20) && this.mode === 2) return true;
20|    if ((s & 0x10) && this.mode === 1) return true;
21|    if ((s & 0x08) && this.mode === 0) return true;
22|    return false;
23|  }
24|  updCoinc(): void {
25|    if (this.ly === this.lyc) this.stat |= 0x04; else this.stat &= ~0x04;
26|  }
27|  info(): { ly: number; mode: 0 | 1 | 2 | 3; dot: number; stat: number; lcdc: number } {
28|    return { ly: this.ly, mode: this.mode, dot: this.dot, stat: (this.stat & 0xf8) | (this.on ? this.mode : 0), lcdc: this.lcdc };
29|  }
30|  readReg(a: number): number {
31|    switch (a) {
32|      case 0xff40: return this.lcdc;
33|      case 0xff41: return (this.stat & 0xf8) | (this.on ? this.mode : 0) | 0x80;
34|      case 0xff42: return this.scy;
35|      case 0xff43: return this.scx;
36|      case 0xff44: return this.ly;
37|      case 0xff45: return this.lyc;
38|      case 0xff47: return this.bgp;
39|      case 0xff48: return this.obp0;
40|      case 0xff49: return this.obp1;
41|      case 0xff4a: return this.wy;
42|      case 0xff4b: return this.wx;
43|      default: return 0xff;
44|    }
45|  }
46|  writeReg(a: number, v: number, raise: (b: number) => void): void {
47|    v &= 0xff;
48|    switch (a) {
49|      case 0xff40: {
50|        const was = this.on; const now = (v & 0x80) !== 0;
51|        this.lcdc = v;
52|        if (was && !now) { this.ly = 0; this.dot = 0; this.mode = 0; this.winLine = 0; this.stat &= ~0x03; this.updCoinc(); this.statLine = false; }
53|        else if (!was && now) { this.dot = 0; this.mode = 2; this.updCoinc(); this.resetStatLine(); this.beginLine(raise); }
54|        else this.checkStat(raise);
55|        break;
56|      }
57|      case 0xff41: this.stat = (this.stat & 0x07) | (v & 0xf8); this.updCoinc(); this.checkStat(raise); break;
58|      case 0xff42: this.scy = v; break;
59|      case 0xff43: this.scx = v; break;
60|      case 0xff45: this.lyc = v; this.updCoinc(); this.checkStat(raise); break;
61|      case 0xff47: this.bgp = v; break;
62|      case 0xff48: this.obp0 = v; break;
63|      case 0xff49: this.obp1 = v; break;
64|      case 0xff4a: this.wy = v; break;
65|      case 0xff4b: this.wx = v; break;
66|    }
67|  }
68|  checkStat(raise: (b: number) => void): void {
69|    const l = this.computeStatLine();
70|    if (l && !this.statLine) raise(1);
71|    this.statLine = l;
72|  }
73|  beginLine(raise: (b: number) => void): void {
74|    if (!this.on || this.ly >= 144) return;
75|    this.m3len = 172 + (this.scx & 7);
76|    let n = 0;
77|    const tall = (this.lcdc & 0x04) !== 0; const h = tall ? 16 : 8;
78|    for (let i = 0; i < 40; i++) {
79|      const y = this.oam[i * 4] - 16;
80|      if (this.ly >= y && this.ly < y + h) { n++; if (n >= 10) break; }
81|    }
82|    this.m3len += n * 6; if (this.m3len > 376) this.m3len = 376;
83|    this.hits["ppu.oam"] = (this.hits["ppu.oam"] || 0) + 1;
84|  }
85|  scanSprites(): number[] {
86|    const out: number[] = [];
87|    if (!(this.lcdc & 0x02)) return out;
88|    const tall = (this.lcdc & 0x04) !== 0; const h = tall ? 16 : 8;
89|    for (let i = 0; i < 40 && out.length < 10; i++) {
90|      const y = this.oam[i * 4] - 16;
91|      if (this.ly >= y && this.ly < y + h) out.push(i);
92|    }
93|    out.sort((a, b) => (this.oam[a * 4 + 1] - this.oam[b * 4 + 1]) || (a - b));
94|    return out;
95|  }
96|  renderLine(): void {
97|    const y = this.ly; if (y >= 144) return;
98|    const row = y * 160;
99|    const pal = [this.bgp & 3, (this.bgp >> 2) & 3, (this.bgp >> 4) & 3, (this.bgp >> 6) & 3];
100|    const bgOn = (this.lcdc & 0x01) !== 0;
101|    const winOn = (this.lcdc & 0x20) !== 0;
102|    const signed = (this.lcdc & 0x10) === 0;
103|    const bgMap = (this.lcdc & 0x08) ? 0x1c00 : 0x1800;
104|    const winMap = (this.lcdc & 0x40) ? 0x1c00 : 0x1800;
105|    const useWin = this.on && winOn && y >= this.wy && this.wx <= 166;
106|    const wx = this.wx - 7;
107|    for (let x = 0; x < 160; x++) {
108|      let ci = 0;
109|      if (!bgOn) ci = 0;
110|      else {
111|        let px = x, prow = y, map = bgMap;
112|        if (useWin && x >= wx) { px = x - wx; prow = this.winLine; map = winMap; }
113|        else if (useWin && x < wx && wx <= 7) { /* bg */ px = (x + this.scx) & 0xff; prow = (y + this.scy) & 0xff; }
114|        else if (useWin && x >= wx) { px = x - wx; prow = this.winLine; map = winMap; }
115|        else { px = (x + this.scx) & 0xff; prow = (y + this.scy) & 0xff; }
116|        const tx = px >> 3, ty = prow >> 3;
117|        let ti = this.vram[map + ty * 32 + tx];
118|        let tn = signed ? 0x1000 + (((ti ^ 0x80) - 0x80) << 4) : (ti << 4);
119|        const r = this.vram[(tn + ((prow & 7) << 1)) & 0x1fff];
120|        const r2 = this.vram[(tn + ((prow & 7) << 1) + 1) & 0x1fff];
121|        const b = 7 - (px & 7);
122|        ci = ((r >> b) & 1) | (((r2 >> b) & 1) << 1);
123|      }
124|      this.fb[row + x] = pal[ci];
125|    }
126|    this.hits["ppu.fetcher"] = (this.hits["ppu.fetcher"] || 0) + 1;
127|    this.hits["ppu.fifo"] = (this.hits["ppu.fifo"] || 0) + 1;
128|    if (useWin) { this.hits["ppu.window"] = (this.hits["ppu.window"] || 0) + 1; this.winLine++; }
129|    const spr = this.scanSprites();
130|    if (spr.length) this.hits["ppu.sprites"] = (this.hits["ppu.sprites"] || 0) + 1;
131|    if (spr.length && this.on) {
132|      const tall = (this.lcdc & 0x04) !== 0;
133|      const bgPrio = new Uint8Array(160);
134|      if (bgOn) {
135|        for (let x = 0; x < 160; x++) {
136|          const v = this.fb[row + x];
137|          bgPrio[x] = (v === pal[0]) ? 0 : 1;
138|        }
139|      }
140|      for (let k = spr.length - 1; k >= 0; k--) {
141|        const i = spr[k]; const o = i * 4;
142|        const sy = this.oam[o] - 16, sx = this.oam[o + 1] - 8;
143|        const tile = this.oam[o + 2], at = this.oam[o + 3];
144|        const palO = [(at & 0x10 ? this.obp1 : this.obp0) & 3, 0, 0, 0];
145|        const p = at & 0x10 ? this.obp1 : this.obp0;
146|        const pc = [(p) & 3, (p >> 2) & 3, (p >> 4) & 3, (p >> 6) & 3];
147|        void palO;
148|        let ry = y - sy; if (at & 0x40) ry = (tall ? 15 : 7) - ry;
149|        let tn2 = tall ? (tile & 0xfe) + (ry >= 8 ? 1 : 0) : tile;
150|        const lr = ry & 7;
151|        const b0 = this.vram[(tn2 * 16 + lr * 2) & 0x1fff];
152|        const b1 = this.vram[(tn2 * 16 + lr * 2 + 1) & 0x1fff];
153|        for (let px2 = 0; px2 < 8; px2++) {
154|          const bx = (at & 0x20) ? px2 : 7 - px2;
155|          const ci2 = ((b0 >> bx) & 1) | (((b1 >> bx) & 1) << 1);
156|          if (ci2 === 0) continue;
157|          const dx = sx + px2; if (dx < 0 || dx >= 160) continue;
158|          if ((at & 0x80) && bgPrio[dx]) continue;
159|          this.fb[row + dx] = pc[ci2];
160|        }
161|      }
162|    }
163|  }
164|  tick(t: number, raise: (b: number) => void): void {
165|    for (let i = 0; i < t; i++) this.tick1(raise);
166|  }
167|  tick1(raise: (b: number) => void): void {
168|    if (!this.on) return;
169|    const prevMode = this.mode; const prevLy = this.ly;
170|    void prevLy;
171|    this.dot++;
172|    if (this.ly < 144) {
173|      const m3end = 80 + this.m3len;
174|      let nm: 0 | 1 | 2 | 3 = this.mode;
175|      if (this.dot <= 80) nm = 2; else if (this.dot <= m3end) nm = 3; else nm = 0;
176|      if (nm !== this.mode) {
177|        this.mode = nm; this.stat = (this.stat & ~0x03) | nm;
178|        if (nm === 0) this.renderLine();
179|        this.checkStat(raise);
180|      }
181|      if (this.dot >= 456) {
182|        this.dot = 0; this.ly++;
183|        this.updCoinc();
184|        if (this.ly === 144) {
185|          this.mode = 1; this.stat = (this.stat & ~0x03) | 1;
186|          raise(0); this.checkStat(raise);
187|        } else {
188|          this.mode = 2; this.stat = (this.stat & ~0x03) | 2;
189|          this.checkStat(raise); this.beginLine(raise);
190|        }
191|      }
192|    } else {
193|      this.mode = 1; this.stat = (this.stat & ~0x03) | 1;
194|      if (this.dot >= 456) {
195|        this.dot = 0; this.ly++;
196|        if (this.ly > 153) {
197|          this.ly = 0; this.winLine = 0; this.mode = 2;
198|          this.stat = (this.stat & ~0x03) | 2;
199|          this.updCoinc(); this.checkStat(raise); this.beginLine(raise);
200|        } else this.updCoinc(), this.checkStat(raise);
201|      }
202|    }
203|    void prevMode;
204|  }
205|}

