1|import type { Core, CoreRegs, CreateCore, HandlerId, Handlers, TelemetryTap } from "../src/schema.ts";
2|import { Cpu } from "./cpu.ts";
3|import type { CpuBus } from "./cpu.ts";
4|import { Ppu } from "./ppu.ts";
5|import { Cart } from "./mbc1.ts";
6|
7|export const HANDLERS: Record<HandlerId, string> = {
8|  "cpu.op": "core/cpu.ts",
9|  "cpu.cb": "core/cpu.ts",
10|  "ppu.oam": "core/ppu.ts",
11|  "ppu.fetcher": "core/ppu.ts",
12|  "ppu.fifo": "core/ppu.ts",
13|  "ppu.window": "core/ppu.ts",
14|  "ppu.sprites": "core/ppu.ts",
15|  "timer": "core/index.ts",
16|  "irq": "core/index.ts",
17|  "dma": "core/index.ts",
18|  "mbc1": "core/mbc1.ts",
19|  "bus.io": "core/index.ts",
20|};
21|
22|const HIDS = ["cpu.op","cpu.cb","ppu.oam","ppu.fetcher","ppu.fifo","ppu.window","ppu.sprites","timer","irq","dma","mbc1","bus.io"] as const;
23|
24|function newHits(): Record<HandlerId, number> {
25|  const o: Record<HandlerId, number> = {};
26|  for (const k of HIDS) o[k] = 0;
27|  return o;
28|}
29|
30|export function createCore(rom: Uint8Array): Core {
31|  const hits = newHits();
32|  const cart = new Cart(rom, hits);
33|  const ppu = new Ppu(hits);
34|  const wram = new Uint8Array(0x2000);
35|  const hram = new Uint8Array(0x80);
36|  const audio = new Uint8Array(0x40);
37|  const audInit: Array<[number, number]> = [
38|    [0x10,0x80],[0x11,0xbf],[0x12,0xf3],[0x14,0xbf],[0x16,0x3f],[0x17,0x00],
39|    [0x19,0xbf],[0x1a,0x7f],[0x1b,0xff],[0x1c,0x9f],[0x1e,0xbf],[0x20,0xff],
40|    [0x21,0x00],[0x22,0x00],[0x23,0xbf],[0x24,0x77],[0x25,0xf3],[0x26,0xf1],
41|  ];
42|  for (const [o,v] of audInit) audio[o & 0x3f] = v;
43|
44|  let div = 0xab00;
45|  let tima = 0, tma = 0, tac = 0xf8;
46|  let prevAnd = 0;
47|  let reload = 0;
48|  let IF = 0xe1, IE = 0x00;
49|  let p1 = 0xcf;
50|  let joyMask = 0;
51|  let sb = 0x00, sc = 0x7e;
52|  let serialText = "";
53|  let dmaOn = false, dmaBase = 0, dmaPos = 0, dmaT = 0;
54|  let cycles = 0;
55|  let onRegWrite: TelemetryTap["onRegWrite"] | undefined = undefined;
56|  const tapHits = hits;
57|
58|  const raise = (b: number): void => { IF = (IF | (1 << b)) & 0xff; };
59|
60|  function timerBit(): number {
61|    const s = tac & 0x03;
62|    return s === 0 ? 9 : s === 1 ? 3 : s === 2 ? 5 : 7;
63|  }
64|  function curAnd(): number {
65|    return (((div >> timerBit()) & 1) & ((tac >> 2) & 1));
66|  }
67|  function incTima(): void {
68|    hits["timer"] = (hits["timer"] || 0) + 1;
69|    if (tima === 0xff) { tima = 0; reload = 4; }
70|    else tima = (tima + 1) & 0xff;
71|  }
72|  function timerStep(): void {
73|    if (reload > 0) {
74|      reload--;
75|      if (reload === 0) { tima = tma & 0xff; IF = (IF | 0x04) & 0xff; }
76|    }
77|    div = (div + 1) & 0xffff;
78|    const c = curAnd();
79|    if (prevAnd === 1 && c === 0) {
80|      if (reload === 0) incTima();
81|    }
82|    prevAnd = c;
83|  }
84|
85|  function peek(a: number): number {
86|    a &= 0xffff;
87|    if (a < 0x8000) return cart.read(a);
88|    if (a < 0xa000) {
89|      return ppu.vram[a - 0x8000] & 0xff;
90|    }
91|    if (a < 0xc000) return cart.readRam(a);
92|    if (a < 0xe000) return wram[a - 0xc000] & 0xff;
93|    if (a < 0xfe00) return wram[a - 0xe000] & 0xff;
94|    if (a < 0xfea0) {
95|      if (dmaOn) return 0xff;
96|      return ppu.oam[a - 0xfe00] & 0xff;
97|    }
98|    if (a < 0xff00) return 0xff;
99|    if (a < 0xff80) return ioRead(a);
100|    if (a < 0xffff) return hram[a - 0xff80] & 0xff;
101|    return IE & 0xff;
102|  }
103|
104|  function ioRead(a: number): number {
105|    switch (a) {
106|      case 0xff00: {
107|        const sel = p1 & 0x30;
108|        const dir = (joyMask & 0x0f);
109|        const btn = ((joyMask >> 4) & 0x0f);
110|        let v = 0x0f;
111|        if ((sel & 0x10) === 0) v &= (~dir) & 0x0f;
112|        if ((sel & 0x20) === 0) v &= (~btn) & 0x0f;
113|        if ((sel & 0x30) === 0x30) v = 0x0f;
114|        return 0xc0 | (sel & 0x30) | (v & 0x0f);
115|      }
116|      case 0xff01: return sb & 0xff;
117|      case 0xff02: return (sc & 0xff) | 0x7c;
118|      case 0xff04: return (div >> 8) & 0xff;
119|      case 0xff05: return tima & 0xff;
120|      case 0xff06: return tma & 0xff;
121|      case 0xff07: return 0xf8 | (tac & 0x07);
122|      case 0xff0f: return 0xe0 | (IF & 0x1f);
123|      case 0xff46: return 0xff;
124|      case 0xff40: case 0xff41: case 0xff42: case 0xff43: case 0xff44:
125|      case 0xff45: case 0xff47: case 0xff48: case 0xff49: case 0xff4a: case 0xff4b:
126|        return ppu.readReg(a);
127|      default:
128|        if (a >= 0xff10 && a <= 0xff3f) {
129|          return audio[a - 0xff00] & 0xff;
130|        }
131|        return 0xff;
132|    }
133|  }
134|
135|  function poke(a: number, v: number): void {
136|    v &= 0xff;
137|    if (a < 0x8000) { cart.write(a, v); return; }
138|    if (a < 0xa000) { ppu.vram[a - 0x8000] = v; return; }
139|    if (a < 0xc000) { cart.writeRam(a, v); return; }
140|    if (a < 0xe000) { wram[a - 0xc000] = v; return; }
141|    if (a < 0xfe00) { wram[a - 0xe000] = v; return; }
142|    if (a < 0xfea0) {
143|      if (!dmaOn) ppu.oam[a - 0xfe00] = v;
144|      return;
145|    }
146|    if (a < 0xff00) return;
147|    if (a < 0xff80) { ioWrite(a, v); return; }
148|    if (a < 0xffff) { hram[a - 0xff80] = v; return; }
149|    IE = v & 0xff;
150|  }
151|
152|  function ioWrite(a: number, v: number): void {
153|    v &= 0xff;
154|    switch (a) {
155|      case 0xff00: p1 = (0xc0 | (v & 0x30) | 0x0f) & 0xff; break;
156|      case 0xff01: sb = v; break;
157|      case 0xff02: {
158|        sc = v;
159|        if ((v & 0x81) === 0x81) {
160|          serialText += String.fromCharCode(sb & 0xff);
161|          sb = 0xff;
162|          raise(3);
163|        }
164|        break;
165|      }
166|      case 0xff04: {
167|        div = 0;
168|        const c = curAnd();
169|        if (prevAnd === 1 && c === 0) { if (reload === 0) incTima(); }
170|        prevAnd = c;
171|        break;
172|      }
173|      case 0xff05:
174|        if (reload > 0) reload = 0;
175|        tima = v;
176|        break;
177|      case 0xff06: tma = v; break;
178|      case 0xff07: {
179|        tac = (v & 0x07) | 0xf8;
180|        const c = curAnd();
181|        if (prevAnd === 1 && c === 0) { if (reload === 0) incTima(); }
182|        prevAnd = c;
183|        break;
184|      }
185|      case 0xff0f: IF = 0xe0 | (v & 0x1f); break;
186|      case 0xff46: {
187|        dmaOn = true; dmaBase = (v << 8) & 0xffff; dmaPos = 0; dmaT = 0;
188|        break;
189|      }
190|      case 0xff40: case 0xff41: case 0xff42: case 0xff43: case 0xff45:
191|      case 0xff47: case 0xff48: case 0xff49: case 0xff4a: case 0xff4b:
192|        ppu.writeReg(a, v, raise);
193|        break;
194|      case 0xff44: break;
195|      default:
196|        if (a >= 0xff10 && a <= 0xff3f) audio[a - 0xff00] = v;
197|        break;
198|    }
199|  }
200|
201|  function dmaStep(): void {
202|    if (!dmaOn) return;
203|    dmaT++;
204|    if (dmaT >= 4) {
205|      dmaT = 0;
206|      const src = (dmaBase + dmaPos) & 0xffff;
207|      let b = 0xff;
208|      if (src < 0x8000) b = cart.read(src);
209|      else if (src < 0xa000) b = ppu.vram[src - 0x8000];
210|      else if (src < 0xc000) b = cart.readRam(src);
211|      else if (src < 0xe000) b = wram[src - 0xc000];
212|      else if (src < 0xfe00) b = wram[src - 0xe000];
213|      else if (src < 0xfea0) b = ppu.oam[src - 0xfe00];
214|      else if (src < 0xff00) b = 0xff;
215|      else if (src < 0xff80) b = ioRead(src);
216|      else if (src < 0xffff) b = hram[src - 0xff80];
217|      else b = IE;
218|      ppu.oam[dmaPos] = b & 0xff;
219|      hits["dma"] = (hits["dma"] || 0) + 1;
220|      dmaPos++;
221|      if (dmaPos >= 160) { dmaOn = false; }
222|    }
223|  }
224|
225|  function tick(n: number): void {
226|    for (let i = 0; i < n; i++) {
227|      cycles++;
228|      timerStep();
229|      ppu.tick1(raise);
230|      dmaStep();
231|    }
232|  }
233|
234|  const cpu = new Cpu(hits);
235|  const bus: CpuBus = {
236|    read(a: number): number {
237|      a &= 0xffff;
238|      tick(4);
239|      return peek(a);
240|    },
241|    write(a: number, v: number): void {
242|      a &= 0xffff; v &= 0xff;
243|      tick(4);
244|      if (a === 0xffff || (a >= 0xff00 && a <= 0xff7f)) {
245|        hits["bus.io"] = (hits["bus.io"] || 0) + 1;
246|        if (onRegWrite) {
247|          const pi = ppu.info();
248|          onRegWrite({ addr: a, value: v, ly: pi.ly, dot: pi.dot, cycles });
249|        }
250|      }
251|      if (a === 0xffff) { IE = v & 0xff; return; }
252|      poke(a, v);
253|    },
254|    idle(): void { tick(4); },
255|    pendingIrqs(): number { return (IF & IE & 0x1f); },
256|    ackIrq(bit: number): void { IF = (IF & ~(1 << bit)) & 0xff; },
257|  };
258|  cpu.attach(bus);
